import { DOMParser, XMLSerializer } from '@xmldom/xmldom';
import { strFromU8, strToU8, unzipSync, zipSync } from 'fflate';

const stylePath = 'score_style.mss';
const unitsPerInch = 254;

export function resizeArchive(data, { pageWidth, pageHeight }) {
  // The archive was just generated by the engine. Only its master-score style
  // changes; notation, breaks, parts and other archive entries are preserved.
  const files = unzipSync(data);
  if (!files[stylePath]) throw new Error('webmscore did not export the master-score style.');
  const document = new DOMParser({
    onError(level, message) {
      if (level !== 'warning') throw new Error('Invalid webmscore page style: ' + message);
    },
  }).parseFromString(strFromU8(files[stylePath]), 'application/xml');
  const style = Array.from(document.documentElement.childNodes).find(node => node.nodeName === 'Style');
  if (!style) throw new Error('webmscore did not export a Style element.');
  const fields = new Map(Array.from(style.childNodes)
    .filter(node => node.nodeType === 1)
    .map(node => [node.nodeName, node]));

  function read(name, fallback = 0) {
    const value = Number(fields.get(name)?.textContent);
    return Number.isFinite(value) && value >= 0 ? value : fallback;
  }

  function write(name, value) {
    const node = fields.get(name) ?? style.appendChild(document.createElement(name));
    node.textContent = String(Number(value.toFixed(8)));
    fields.set(name, node);
  }

  if (pageWidth !== undefined) {
    const width = pageWidth / unitsPerInch;
    const oldWidth = read('pageWidth', 8.27);
    const margins = Math.max(0, oldWidth - read('pagePrintableWidth', oldWidth));
    const newMargins = Math.min(margins, width / 2);
    if (newMargins < margins) {
      for (const side of ['Even', 'Odd']) {
        const field = 'page' + side + 'LeftMargin';
        write(field, Math.min(read(field), margins) * newMargins / margins);
      }
    }
    write('pageWidth', width);
    write('pagePrintableWidth', width - newMargins);
  }

  if (pageHeight !== undefined) {
    const height = pageHeight / unitsPerInch;
    for (const side of ['Even', 'Odd']) {
      const top = 'page' + side + 'TopMargin';
      const bottom = 'page' + side + 'BottomMargin';
      const total = read(top) + read(bottom);
      if (total > height / 2) {
        const scale = height / (2 * total);
        write(top, read(top) * scale);
        write(bottom, read(bottom) * scale);
      }
    }
    write('pageHeight', height);
  }

  files[stylePath] = strToU8(new XMLSerializer().serializeToString(document));
  return zipSync(files);
}
